int power_up(int base, int k) {
    // k 0 asel tar result 1
    if (k == 0) {
        return 1;
    }

    int result = 1;
    // base cha k vela guna kara
    for (int i = 0; i < k; i = i + 1) {
        result = result * base;
    }

    return result;
}
